// Yeteneğin ikonu (satır içi SVG); ikonu yoksa boş dizge döner, çağıran eski tür ikonuna düşer.
// 23 Kas (C9, GPT G6): boyalı yetenek kartları (js/gorsel-png.js içinde, 203 simge; js/sahne.js yükler). Arkada yüklenir; yüklenene dek ve kartı olmayan
// yetenekte eski siluet (game-icons) çizilir. Çerçeveyi oyun ekler (kart 256 → 112 px, kenarlardan 16 px boş).
import { gorsel } from './sahne.js'; // G6 simgeleri gorsel-png.js içinde
export const skillIcon = id => { const YP = gorsel(); return (YP?.has(id) ? `<img class="yico-png" src="${YP.url(id)}" alt="" draggable="false">` : SKILL_ICONS[id] ? `<svg viewBox="0 0 512 512" aria-hidden="true"><path d="${SKILL_ICONS[id]}"/></svg>` : ''); };
